import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"@jsprismarine/bedrock-data","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"@jsprismarine/bedrock-data"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/bedrock-data/"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/bedrock-data/"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/bedrock-data/src"}},"headers":[],"relativePath":"api/@jsprismarine/bedrock-data/index.md","filePath":"api/@jsprismarine/bedrock-data/index.md","lastUpdated":1793391964000}`),a={name:`api/@jsprismarine/bedrock-data/index.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../">API reference</a> / @jsprismarine/bedrock-data</p><h1 id="jsprismarine-bedrock-data" tabindex="-1">@jsprismarine/bedrock-data <a class="header-anchor" href="#jsprismarine-bedrock-data" aria-label="Permalink to “@jsprismarine/bedrock-data”">​</a></h1><p><a href="https://github.com/JSPrismarine/JSPrismarine/blob/master/LICENSE" target="_blank" rel="noreferrer"><img src="https://img.shields.io/github/license/JSPrismarine/JSPrismarine" alt="License"></a><a href="https://discord.gg/kZZCDyCBbW" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/704967868885762108?color=%237289DA&amp;label=Discord" alt="Join the Discord Server"></a><a href="https://www.npmjs.com/package/@jsprismarine/bedrock-data" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/dt/@jsprismarine/bedrock-data" alt="npm"></a></p><p>Minecraft Bedrock game data exported in a nodejs friendly way.</p><h2 id="where-the-data-comes-from" tabindex="-1">Where the data comes from <a class="header-anchor" href="#where-the-data-comes-from" aria-label="Permalink to “Where the data comes from”">​</a></h2><ul><li><code>src/jsp/</code> is captured from a Bedrock Dedicated Server 1.26.51.1 by <code>pnpm run dump:bedrock</code>. The item table and the three payloads a client refuses to join without live at the top level, the Script API registries under <code>src/jsp/bedrock/</code>, the raw engine tables under <code>src/jsp/packets/</code>, and the reference world in <code>src/jsp/reference_world.json</code>.</li><li><code>src/resources/</code> is a link to a pinned download of <a href="https://github.com/CloudburstMC/Data" target="_blank" rel="noreferrer">CloudburstMC/Data</a>, the Apache-2.0 dumps of the Bedrock tables. <code>utils/build.js</code> reads the creative menu, the actor identifiers, and the two item columns the capture does not record: each item&#39;s version and its component NBT. See <a href="#pinned-upstream-sources">Pinned upstream sources</a> for how to fetch it and how to pick a Bedrock version.</li><li><code>src/vendor/</code> is data neither of the two carries, copied from projects that do. See <a href="./../../_media/README.html">its README</a> for the source and license of each file.</li><li><code>src/jsp/java/</code> is dumped from the Java Edition 26.3 server jar, which Mojang ships unobfuscated since 26.1. <code>block_properties.json</code> holds the per-state block properties no Mojang report carries (hardness, blast resistance, friction, light, map color, sound type, push reaction, instrument, fire odds and the rest), with state-invariant values once per block and per-state differences under <code>stateOverrides</code>. <code>entity_attributes.json</code> holds the default attribute values, dimensions and category for the 93 entity types with an attribute supplier. See the next section for how to refresh them.</li></ul><h2 id="refreshing-the-java-goldens" tabindex="-1">Refreshing the Java goldens <a class="header-anchor" href="#refreshing-the-java-goldens" aria-label="Permalink to “Refreshing the Java goldens”">​</a></h2><p><code>pnpm run dump:java</code> is a capture-time task, run on a Java version bump rather than as part of the build. It downloads the pinned server jar through the piston-meta manifest chain, verifies its sha1, unpacks the bundler, compiles <code>utils/java-dump/DumpJavaData.java</code> against the server classes, runs it, and rewrites the two files under <code>src/jsp/java/</code>. Everything downloaded stays under <code>node_modules/.cache/jsprismarine/java/</code>.</p><p>The pinned version, its sha1 and the manifest URL are constants at the top of <code>utils/java-dump/run.mjs</code>. The dumper needs a JDK matching the jar&#39;s class file version (Java 25 for 26.3); the script finds one through <code>JSP_JAVA_HOME</code>, <code>JAVA_HOME</code> or, on macOS, <code>/usr/libexec/java_home</code>. <code>src/javaGoldens.test.ts</code> checks the shape of both files and the counts measured in <code>docs/research/java-code-only-behavior.md</code>; a version bump updates those counts with the goldens.</p><p>The root test command and <code>@jsprismarine/worldgen</code> test and vector commands prepare the inner server jar automatically. They download and verify the pinned outer jar, then cache its inner server jar under <code>node_modules/.cache/jsprismarine/java/</code>. This step does not run Java or change captured data. Set <code>JSP_JAVA_SERVER_JAR</code> to use an existing inner jar, or run <code>pnpm --filter @jsprismarine/bedrock-data run ensure:java-server</code> to prepare it separately.</p><h2 id="refreshing-the-bedrock-captures" tabindex="-1">Refreshing the Bedrock captures <a class="header-anchor" href="#refreshing-the-bedrock-captures" aria-label="Permalink to “Refreshing the Bedrock captures”">​</a></h2><p><code>pnpm run dump:bedrock</code> is the other half of the same capture-time task, run on a Bedrock version bump and weekly rather than as part of the build. It copies the fetched server into <code>node_modules/.cache/jsprismarine/bds-run/&lt;version&gt;/</code>, makes the binary executable, turns the content log on, and drives four passes over the console, each with a world of its own:</p><table tabindex="0"><thead><tr><th>Pass</th><th>What it does</th><th>What it writes</th></tr></thead><tbody><tr><td><code>dump</code></td><td>Runs the dump behavior pack, which walks every Script API registry</td><td><code>src/jsp/v&lt;protocol&gt;/bedrock/&lt;table&gt;.json</code></td></tr><tr><td><code>refworld</code></td><td>Generates the reference region through ticking areas, then reduces the saved world</td><td><code>src/jsp/v&lt;protocol&gt;/reference_world.json</code></td></tr><tr><td><code>packets</code></td><td>Logs a client in and records what the server sends it</td><td><code>src/jsp/v&lt;protocol&gt;/*.json</code>, <code>*.nbt</code>, <code>packets/*.bin</code></td></tr><tr><td><code>palette</code></td><td>Places every block type, then asks the game which values each property takes</td><td><code>packages/minecraft/datagen/snapshot/v&lt;protocol&gt;/block-palette.json</code></td></tr></tbody></table><p>Run one pass with <code>--pass</code>, and pass <code>--force</code> to copy the server again:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;">pnpm</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;"> run</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;"> dump:bedrock</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;"> --pass</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;"> refworld</span></span></code></pre></div><h3 id="where-the-capture-can-run" tabindex="-1">Where the capture can run <a class="header-anchor" href="#where-the-capture-can-run" aria-label="Permalink to “Where the capture can run”">​</a></h3><p>Mojang publishes the server for Linux x86-64 and Windows, and <code>sources.json</code> pins the Linux zip. On a Linux x86-64 machine <code>dump:bedrock</code> starts that binary directly, which is also what <code>.github/workflows/capture.yml</code> does on its <code>ubuntu-latest</code> runner. On any other host, an Apple Silicon Mac or a Linux arm64 box, it starts the same staged copy inside a Linux x86-64 container instead. You get the same four passes and the same files in the same places; only the thing that executes the binary changes.</p><p>The container path needs a container runtime whose daemon is running. The capture tries <code>docker</code> and then <code>podman</code>, and it asks each one for its <em>server</em> version rather than just looking on your <code>PATH</code>, because an installed Docker CLI with Docker Desktop stopped is the common case and it cannot start anything. If neither answers, the capture stops before it stages anything and tells you what to install or start.</p><p>Nothing is built or pulled that contains Mojang&#39;s binary. The container mounts the run directory under <code>node_modules/.cache/jsprismarine/bds-run/&lt;version&gt;/</code>, which already holds the copy the capture staged from the fetch cache, and runs <code>./bedrock_server</code> out of the mount. The image is a stock <code>docker.io/library/ubuntu:24.04</code>, chosen because the server is dynamically linked against the glibc and libstdc++ of a recent Ubuntu and because redistributing the server in an image of our own is not something this project does. The server&#39;s UDP ports are published on <code>127.0.0.1</code> only, for the <code>packets</code> pass&#39;s client, and the container is removed when the run ends or when you interrupt it.</p><p>On an arm64 host the image is an emulated <code>linux/amd64</code> one, running under Rosetta or qemu. Expect it to be several times slower than a native run, and <code>refworld</code>, already the longest pass, to be the one you wait on. The capture prints a warning when it starts under emulation, and it multiplies every stage timeout by four so that a slow run reports a stall only when something is genuinely stuck.</p><p>Four environment variables steer this, alongside the rest of the pipeline&#39;s <code>JSP_*</code> overrides:</p><table tabindex="0"><thead><tr><th>Variable</th><th>What it does</th></tr></thead><tbody><tr><td><code>JSP_BDS_RUNNER</code></td><td><code>auto</code> (the default), <code>native</code>, or <code>container</code>. <code>docker</code> and <code>podman</code> also select <code>container</code>.</td></tr><tr><td><code>JSP_BDS_CONTAINER_CLI</code></td><td>The CLI to use instead of probing for one, for anything that takes <code>docker run</code> arguments.</td></tr><tr><td><code>JSP_BDS_CONTAINER_IMAGE</code></td><td>A different base image, if the stock Ubuntu is missing a shared object your server version wants.</td></tr><tr><td><code>JSP_BDS_PATH</code></td><td>An unpacked server to capture, instead of the fetch cache. Works on either runner.</td></tr></tbody></table><p>Forcing a runner is for diagnosis. <code>JSP_BDS_RUNNER=container</code> on a Linux x86-64 machine is how you reproduce a container-only problem, and <code>JSP_BDS_RUNNER=native</code> makes the capture fail loudly rather than quietly fall back when you expected the host&#39;s own CPU to be used.</p><h3 id="the-reference-world" tabindex="-1">The reference world <a class="header-anchor" href="#the-reference-world" aria-label="Permalink to “The reference world”">​</a></h3><p><code>src/jsp/reference_world.json</code> is what <code>packages/parity/</code> compares a generator against, and <code>utils/bedrock-dump/region.ts</code> is the definition of &quot;the reference region&quot;: a fixed seed, the Overworld, and 400 chunks at the world origin. Per chunk the file carries a sha256 of the stored heightmap, of the 3D biome arrays, of the topmost non-air block name per column, and of the layer 0 block states; plus the chunk&#39;s sorted block identifiers, its block entity count and its <code>FinalizedState</code>. Sixteen chunks at the origin are also kept whole, as plain arrays, so a failing digest can be read rather than guessed at, and one block histogram covers the region.</p><p>The four digests are the four rows Phase 4 of <a href="https://github.com/JSPrismarine/JSPrismarine/blob/master/docs/plans/data-driven-vanilla.md" target="_blank" rel="noreferrer">the plan</a> exits on. A generator that produces the same world reproduces every one of them exactly.</p><h2 id="pinned-upstream-sources" tabindex="-1">Pinned upstream sources <a class="header-anchor" href="#pinned-upstream-sources" aria-label="Permalink to “Pinned upstream sources”">​</a></h2><p><code>sources.json</code> pins the upstream publications the data pipeline reads: the Bedrock Dedicated Server zip, Mojang/bedrock-samples, the Java Edition server jar, SpyglassMC/vanilla-mcdoc, GeyserMC/mappings and CloudburstMC/Data, each with a version, URL and hash.</p><p><code>pnpm run fetch:sources</code> downloads each source into <code>node_modules/.cache/jsprismarine/&lt;source&gt;/&lt;version&gt;/</code>, verifies its hash before unpacking, and skips sources whose verified content is already cached. It then writes <code>pack-hashes.json</code>, a sha256 per top-level folder of each source, so a version bump shows which folders changed. For offline work, <code>JSP_BDS_PATH</code>, <code>JSP_JAVA_JAR_PATH</code>, <code>JSP_BEDROCK_SAMPLES_PATH</code>, <code>JSP_VANILLA_MCDOC_PATH</code>, <code>JSP_GEYSER_MAPPINGS_PATH</code> and <code>JSP_CLOUDBURST_DATA_PATH</code> point at local copies and bypass the download.</p><h3 id="picking-a-bedrock-version" tabindex="-1">Picking a Bedrock version <a class="header-anchor" href="#picking-a-bedrock-version" aria-label="Permalink to “Picking a Bedrock version”">​</a></h3><p>CloudburstMC/Data is pinned once per Bedrock protocol version, under <code>versions</code> in <code>sources.json</code>. Each version caches under its own <code>cloudburst-data/v&lt;protocol&gt;/</code> directory, so several versions&#39; dumps sit side by side.</p><p><code>pnpm run fetch:cloudburst</code> fetches the version in <code>defaultProtocolVersion</code> and links it to <code>src/resources</code>; <code>pnpm run fetch:cloudburst -- --protocol 2225</code> picks another. <code>pnpm run generate</code> fetches before it builds, so a fresh clone needs no extra step. Only the files under <code>extract</code> are unpacked, <code>LICENSE</code> among them: the dumps are Apache-2.0 and the license travels with them.</p><h2 id="running-the-java-data-generator" tabindex="-1">Running the Java data generator <a class="header-anchor" href="#running-the-java-data-generator" aria-label="Permalink to “Running the Java data generator”">​</a></h2><p><code>pnpm run datagen:java</code> runs Mojang&#39;s own data generator against the fetched server jar, after re-checking the jar&#39;s sha1 against <code>sources.json</code>. One run produces both halves of the Java data the rest of the repository reads, under the same gitignored cache:</p><ul><li><code>vanilla-datapack/&lt;version&gt;/</code>, the vanilla datapack. <code>@jsprismarine/packs</code> loads it as the Java member of the pack stack, the overworld generator reads its <code>worldgen/*</code> registries and block tags, and the loot, advancement, predicate, enchantment and feature corpus suites read it.</li><li><code>java-reports/&lt;version&gt;/generated/reports/</code>, the data reports. The mapping and item table generators read them, and the overworld generator reads <code>biome_parameters</code> from them.</li><li><code>java-structures/&lt;version&gt;/</code>, the 1511 structure templates. The data generator writes no NBT, so these come straight out of the jar; <code>pnpm run extract:structures</code> does that step on its own, for a checkout with no JDK.</li></ul><p>The templates matter for speed rather than for correctness. The world generator can read them out of the jar, but that means inflating all 17655 of its entries on the first template a world places, inside chunk generation. The extracted directory is read one file at a time instead.</p><p>The generator writes no <code>pack.mcmeta</code>, so this step writes one from the <code>pack_version</code> the jar declares in its <code>version.json</code>; that file is what marks the directory as a loadable datapack. The same <code>version.json</code> names the JDK the jar needs, found through <code>JSP_JAVA_HOME</code>, <code>JAVA_HOME</code>, the <code>java</code> on <code>PATH</code> or, on macOS, <code>/usr/libexec/java_home</code>. The pinned Java Edition 26.3 jar asks for JDK 25 or newer; an older <code>java</code> earlier on <code>PATH</code> is skipped rather than used.</p><p>A second run is a no-op once all three directories hold the files the step checks for. Pass <code>--force</code> to regenerate:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;">pnpm</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;"> run</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;"> datagen:java</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;"> --</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;"> --force</span></span></code></pre></div><p>The output is about 53 MB of Mojang&#39;s content and is never committed. <code>JSP_VANILLA_DATAPACK</code> and <code>JSP_JAVA_REPORTS</code> point consumers at a copy produced elsewhere.</p><h3 id="doing-it-in-one-step" tabindex="-1">Doing it in one step <a class="header-anchor" href="#doing-it-in-one-step" aria-label="Permalink to “Doing it in one step”">​</a></h3><p><code>pnpm run ensure:worldgen</code> is the same work arranged for somebody who just wants a server running. It checks the three directories, and only if something is missing does it download the jar and run the generator. <code>pnpm dev</code> at the repository root runs it first, which is what makes <code>pnpm install &amp;&amp; pnpm dev</code> enough on a clean clone.</p><p>On a complete cache it compares file names and exits, so repeat runs cost a fraction of a second and touch no network. When it cannot finish it prints one line saying why rather than a stack trace: no JDK, no network, or a generator that failed. It asks about the JDK before downloading the jar, so a machine without Java finds out immediately.</p><p><code>pnpm install</code> deliberately does not do this. The jar is a 62 MB download that only somebody running a server needs, and builds, tests and CI arrange their own data.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h2><p>To install <code>@jsprismarine/bedrock-data</code>, use the following command:</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span>pnpm install @jsprismarine/bedrock-data --save</span></span></code></pre></div><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to “Interfaces”">​</a></h2><h3 id="blockdefinitionentry" tabindex="-1">BlockDefinitionEntry <a class="header-anchor" href="#blockdefinitionentry" aria-label="Permalink to “BlockDefinitionEntry”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L75" target="_blank" rel="noreferrer">index.ts:75</a></p><p>A vanilla block the client only knows if the server declares it.</p><h4 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h4><h5 id="definition" tabindex="-1">definition <a class="header-anchor" href="#definition" aria-label="Permalink to “definition”">​</a></h5><blockquote><p><strong>definition</strong>: <code>Buffer</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L78" target="_blank" rel="noreferrer">index.ts:78</a></p><p>The definition as network NBT, exactly as a Bedrock Dedicated Server sends it.</p><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h5><blockquote><p><strong>name</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L76" target="_blank" rel="noreferrer">index.ts:76</a></p><hr><h3 id="creativegroupentry" tabindex="-1">CreativeGroupEntry <a class="header-anchor" href="#creativegroupentry" aria-label="Permalink to “CreativeGroupEntry”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/generated/creativeitems.ts#L4" target="_blank" rel="noreferrer">generated/creativeitems.ts:4</a></p><p>One heading of the creative menu, with the item the client draws beside it.</p><h4 id="properties-1" tabindex="-1">Properties <a class="header-anchor" href="#properties-1" aria-label="Permalink to “Properties”">​</a></h4><h5 id="category" tabindex="-1">category <a class="header-anchor" href="#category" aria-label="Permalink to “category”">​</a></h5><blockquote><p><strong>category</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/generated/creativeitems.ts#L8" target="_blank" rel="noreferrer">generated/creativeitems.ts:8</a></p><p>Which tab the heading sits in: <code>construction</code>, <code>nature</code>, <code>equipment</code> or <code>items</code>.</p><h5 id="icon" tabindex="-1">icon <a class="header-anchor" href="#icon" aria-label="Permalink to “icon”">​</a></h5><blockquote><p><strong>icon</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/generated/creativeitems.ts#L10" target="_blank" rel="noreferrer">generated/creativeitems.ts:10</a></p><p>The item name shown beside the heading.</p><h5 id="icon-block-states" tabindex="-1">icon_block_states? <a class="header-anchor" href="#icon-block-states" aria-label="Permalink to “icon_block_states?”">​</a></h5><blockquote><p><code>optional</code> <strong>icon_block_states?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/generated/creativeitems.ts#L15" target="_blank" rel="noreferrer">generated/creativeitems.ts:15</a></p><p>The block state the icon shows, as base64 little-endian NBT whose <code>network_id</code> is the hashed block runtime id vanilla puts on the wire. Absent when the icon is not a block.</p><h5 id="name-1" tabindex="-1">name <a class="header-anchor" href="#name-1" aria-label="Permalink to “name”">​</a></h5><blockquote><p><strong>name</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/generated/creativeitems.ts#L6" target="_blank" rel="noreferrer">generated/creativeitems.ts:6</a></p><p>A translation key such as <code>itemGroup.name.planks</code>.</p><hr><h3 id="creativeitementry" tabindex="-1">CreativeItemEntry <a class="header-anchor" href="#creativeitementry" aria-label="Permalink to “CreativeItemEntry”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/generated/creativeitems.ts#L19" target="_blank" rel="noreferrer">generated/creativeitems.ts:19</a></p><p>One entry of the creative menu as the client orders it.</p><h4 id="properties-2" tabindex="-1">Properties <a class="header-anchor" href="#properties-2" aria-label="Permalink to “Properties”">​</a></h4><h5 id="block-states" tabindex="-1">block_states? <a class="header-anchor" href="#block-states" aria-label="Permalink to “block_states?”">​</a></h5><blockquote><p><code>optional</code> <strong>block_states?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/generated/creativeitems.ts#L28" target="_blank" rel="noreferrer">generated/creativeitems.ts:28</a></p><p>The block state the entry places, as base64 little-endian NBT whose <code>network_id</code> is the hashed block runtime id vanilla puts on the wire. Absent when the entry is not a block, which includes the item form of doors, beds and hanging signs.</p><h5 id="group" tabindex="-1">group <a class="header-anchor" href="#group" aria-label="Permalink to “group”">​</a></h5><blockquote><p><strong>group</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/generated/creativeitems.ts#L22" target="_blank" rel="noreferrer">generated/creativeitems.ts:22</a></p><p>Which of <a href="#creative-groups">creative_groups</a> the entry is filed under, by index.</p><h5 id="meta" tabindex="-1">meta? <a class="header-anchor" href="#meta" aria-label="Permalink to “meta?”">​</a></h5><blockquote><p><code>optional</code> <strong>meta?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/generated/creativeitems.ts#L29" target="_blank" rel="noreferrer">generated/creativeitems.ts:29</a></p><h5 id="name-2" tabindex="-1">name <a class="header-anchor" href="#name-2" aria-label="Permalink to “name”">​</a></h5><blockquote><p><strong>name</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/generated/creativeitems.ts#L20" target="_blank" rel="noreferrer">generated/creativeitems.ts:20</a></p><h5 id="nbt" tabindex="-1">nbt? <a class="header-anchor" href="#nbt" aria-label="Permalink to “nbt?”">​</a></h5><blockquote><p><code>optional</code> <strong>nbt?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/generated/creativeitems.ts#L30" target="_blank" rel="noreferrer">generated/creativeitems.ts:30</a></p><hr><h3 id="itemtypeentry" tabindex="-1">ItemTypeEntry <a class="header-anchor" href="#itemtypeentry" aria-label="Permalink to “ItemTypeEntry”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L11" target="_blank" rel="noreferrer">index.ts:11</a></p><p>One item as the item table names it.</p><h4 id="properties-3" tabindex="-1">Properties <a class="header-anchor" href="#properties-3" aria-label="Permalink to “Properties”">​</a></h4><h5 id="component-based" tabindex="-1">component_based <a class="header-anchor" href="#component-based" aria-label="Permalink to “component_based”">​</a></h5><blockquote><p><strong>component_based</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L15" target="_blank" rel="noreferrer">index.ts:15</a></p><p>Whether the item is defined by components rather than being one the client already knows.</p><h5 id="runtime-id" tabindex="-1">runtime_id <a class="header-anchor" href="#runtime-id" aria-label="Permalink to “runtime_id”">​</a></h5><blockquote><p><strong>runtime_id</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L13" target="_blank" rel="noreferrer">index.ts:13</a></p><p>The numeric id the client will know this name by. Negative for a block&#39;s item form.</p><h5 id="version" tabindex="-1">version <a class="header-anchor" href="#version" aria-label="Permalink to “version”">​</a></h5><blockquote><p><strong>version</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L24" target="_blank" rel="noreferrer">index.ts:24</a></p><p><code>Item Version</code> as <code>ItemRegistryPacket</code> carries it: 0 <code>Legacy</code>, 1 <code>DataDriven</code>, 2 <code>None</code>.</p><p>A <code>DataDriven</code> item is one the client builds from <a href="#item-components">item_components</a>; a Bedrock Dedicated Server sends 31 vanilla items that way (the bundles, the spears, the trial keys, the apple). Most vanilla items are <code>None</code>, including 44 that are <code>component_based</code> and still travel with an empty compound, such as the arrow, the cake and the music discs.</p><hr><h3 id="javaentityattributes" tabindex="-1">JavaEntityAttributes <a class="header-anchor" href="#javaentityattributes" aria-label="Permalink to “JavaEntityAttributes”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L144" target="_blank" rel="noreferrer">index.ts:144</a></p><p>One Java entity type&#39;s hitbox and the attributes its class declares.</p><h4 id="properties-4" tabindex="-1">Properties <a class="header-anchor" href="#properties-4" aria-label="Permalink to “Properties”">​</a></h4><h5 id="attributes" tabindex="-1">attributes <a class="header-anchor" href="#attributes" aria-label="Permalink to “attributes”">​</a></h5><blockquote><p><strong>attributes</strong>: <code>Record</code>&lt;<code>string</code>, <code>number</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L152" target="_blank" rel="noreferrer">index.ts:152</a></p><p>Java attribute id to its base value, such as <code>minecraft:max_health</code>.</p><h5 id="category-1" tabindex="-1">category <a class="header-anchor" href="#category-1" aria-label="Permalink to “category”">​</a></h5><blockquote><p><strong>category</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L146" target="_blank" rel="noreferrer">index.ts:146</a></p><p>The <code>MobCategory</code> the class belongs to, such as <code>monster</code> or <code>creature</code>.</p><h5 id="height" tabindex="-1">height <a class="header-anchor" href="#height" aria-label="Permalink to “height”">​</a></h5><blockquote><p><strong>height</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L150" target="_blank" rel="noreferrer">index.ts:150</a></p><p>The hitbox height in blocks, which Bedrock writes as <code>minecraft:collision_box.height</code>.</p><h5 id="width" tabindex="-1">width <a class="header-anchor" href="#width" aria-label="Permalink to “width”">​</a></h5><blockquote><p><strong>width</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L148" target="_blank" rel="noreferrer">index.ts:148</a></p><p>The hitbox width in blocks, which Bedrock writes as <code>minecraft:collision_box.width</code>.</p><hr><h3 id="javaentitynavigationentry" tabindex="-1">JavaEntityNavigationEntry <a class="header-anchor" href="#javaentitynavigationentry" aria-label="Permalink to “JavaEntityNavigationEntry”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L166" target="_blank" rel="noreferrer">index.ts:166</a></p><p>One Java mob&#39;s navigation, path costs, and entity-push behavior.</p><h4 id="properties-5" tabindex="-1">Properties <a class="header-anchor" href="#properties-5" aria-label="Permalink to “Properties”">​</a></h4><h5 id="canfloat" tabindex="-1">canFloat <a class="header-anchor" href="#canfloat" aria-label="Permalink to “canFloat”">​</a></h5><blockquote><p><strong>canFloat</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L170" target="_blank" rel="noreferrer">index.ts:170</a></p><p>Whether Java&#39;s registered goals enabled floating through liquid.</p><h5 id="cannavigateground" tabindex="-1">canNavigateGround <a class="header-anchor" href="#cannavigateground" aria-label="Permalink to “canNavigateGround”">​</a></h5><blockquote><p><strong>canNavigateGround</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L172" target="_blank" rel="noreferrer">index.ts:172</a></p><p>Whether Java&#39;s navigator can follow paths on solid ground.</p><h5 id="navigationclass" tabindex="-1">navigationClass <a class="header-anchor" href="#navigationclass" aria-label="Permalink to “navigationClass”">​</a></h5><blockquote><p><strong>navigationClass</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L168" target="_blank" rel="noreferrer">index.ts:168</a></p><p>The Java path-navigation class instantiated for the entity type.</p><h5 id="pathfindingmalus" tabindex="-1">pathfindingMalus <a class="header-anchor" href="#pathfindingmalus" aria-label="Permalink to “pathfindingMalus”">​</a></h5><blockquote><p><strong>pathfindingMalus</strong>: <code>Record</code>&lt;<code>string</code>, <code>number</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L176" target="_blank" rel="noreferrer">index.ts:176</a></p><p>Java&#39;s per-<code>PathType</code> route cost, with negative values marking blocked terrain.</p><h5 id="pushable" tabindex="-1">pushable <a class="header-anchor" href="#pushable" aria-label="Permalink to “pushable”">​</a></h5><blockquote><p><strong>pushable</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L174" target="_blank" rel="noreferrer">index.ts:174</a></p><p>Whether Java lets this living entity push and be pushed by other entities.</p><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to “Variables”">​</a></h2><h3 id="biome-definitions-network" tabindex="-1">biome_definitions_network <a class="header-anchor" href="#biome-definitions-network" aria-label="Permalink to “biome_definitions_network”">​</a></h3><blockquote><p><code>const</code> <strong>biome_definitions_network</strong>: <code>Buffer</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L138" target="_blank" rel="noreferrer">index.ts:138</a></p><p>The vanilla biome definitions, as <code>BiomeDefinitionListPacket</code> carries them at protocol 2193: the whole payload of the packet a Bedrock Dedicated Server 1.26.51.1 sends, replayed verbatim.</p><p>At 1.26.x the packet became a map of biome data plus a shared string table the entries index into. An empty one is no longer enough - a client reaches the world-generation screen with no biomes and gives up - so a server that generates any world has to send the real thing.</p><hr><h3 id="block-definitions" tabindex="-1">block_definitions <a class="header-anchor" href="#block-definitions" aria-label="Permalink to “block_definitions”">​</a></h3><blockquote><p><code>const</code> <strong>block_definitions</strong>: readonly <a href="#blockdefinitionentry"><code>BlockDefinitionEntry</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L89" target="_blank" rel="noreferrer">index.ts:89</a></p><p>The data driven vanilla blocks, and the definitions a client needs to draw them.</p><p>Since 1.26.50 vanilla defines some of its own blocks in data rather than in the client - the wool stairs and slabs, the concrete slabs - and a server has to declare them in <code>StartGamePacket</code> the way it would a plugin&#39;s. Captured from the same server as the item table, by the same tool; each definition is handed back to the wire verbatim.</p><hr><h3 id="creative-groups" tabindex="-1">creative_groups <a class="header-anchor" href="#creative-groups" aria-label="Permalink to “creative_groups”">​</a></h3><blockquote><p><code>const</code> <strong>creative_groups</strong>: <a href="#creativegroupentry"><code>CreativeGroupEntry</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/generated/creativeitems.ts#L46" target="_blank" rel="noreferrer">generated/creativeitems.ts:46</a></p><p>The headings of the creative menu, in the order the client draws them.</p><hr><h3 id="creativeitems" tabindex="-1">creativeitems <a class="header-anchor" href="#creativeitems" aria-label="Permalink to “creativeitems”">​</a></h3><blockquote><p><code>const</code> <strong>creativeitems</strong>: <a href="#creativeitementry"><code>CreativeItemEntry</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/generated/creativeitems.ts#L173" target="_blank" rel="noreferrer">generated/creativeitems.ts:173</a></p><hr><h3 id="entity-identifiers" tabindex="-1">entity_identifiers <a class="header-anchor" href="#entity-identifiers" aria-label="Permalink to “entity_identifiers”">​</a></h3><blockquote><p><code>const</code> <strong>entity_identifiers</strong>: <code>Buffer</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L121" target="_blank" rel="noreferrer">index.ts:121</a></p><p>Every actor type a client may be asked to render, as <code>AvailableActorIdentifiersPacket</code> carries it: one network NBT compound holding an <code>idlist</code>, replayed verbatim.</p><hr><h3 id="item-components" tabindex="-1">item_components <a class="header-anchor" href="#item-components" aria-label="Permalink to “item_components”">​</a></h3><blockquote><p><code>const</code> <strong>item_components</strong>: <code>Readonly</code>&lt;<code>Record</code>&lt;<code>string</code>, <code>Buffer</code>&gt;&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L63" target="_blank" rel="noreferrer">index.ts:63</a></p><p>Item name to its <code>Item Component Data</code>, as network NBT, for every item that has any.</p><p>A Bedrock Dedicated Server sends 78 vanilla items with a non-empty compound: the 31 <code>DataDriven</code> entries of <a href="#item-table">item_table</a>, which the client cannot build without one, and 47 foods that are not <code>component_based</code> yet carry their <code>minecraft:food</code> values anyway. Every other item travels with the empty compound, and is absent here.</p><p>From the submodule&#39;s <code>item_components.nbt</code>, a dump of 1.26.50 at the same protocol as the item table. <code>utils/build.js</code> converts each item&#39;s compound from the on-disk NBT flavor to the network one tag by tag, so a server writes the bytes to the wire as they are.</p><hr><h3 id="item-table" tabindex="-1">item_table <a class="header-anchor" href="#item-table" aria-label="Permalink to “item_table”">​</a></h3><blockquote><p><code>const</code> <strong>item_table</strong>: <code>Record</code>&lt;<code>string</code>, <a href="#itemtypeentry"><code>ItemTypeEntry</code></a>&gt; = <code>item_table_data</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L49" target="_blank" rel="noreferrer">index.ts:49</a></p><p>The item table: every name the client can be told about, and the number it travels as.</p><p>The authority on the mapping - the client builds its registry from what we send, so everything naming an item has to agree with this one file.</p><p>Captured from a Bedrock Dedicated Server 1.26.51.1, not taken from a third party: the server sends it as <code>ItemRegistryPacket</code>, so a client that can log in can simply record it. <code>packages/client/tools/capture-server-data.mjs</code> is that client, and its output is <code>jsp/v&lt;protocol&gt;/required_item_list.json</code>. It stays under <code>jsp/</code> rather than moving to <code>resources/</code> because a capture of the version this server targets is the thing nothing else can promise.</p><p>The capture records no <code>version</code>. <code>utils/build.js</code> takes that one column from the submodule&#39;s <code>runtime_item_states.json</code>, a dump of 1.26.50 at the same protocol, and refuses to generate the table unless the two agree on every name, id and component flag. They do.</p><p>The version matters more than it looks. Against the 1.21.40 table this has 240 names it did not, and - the part that breaks quietly - <strong>528 items whose number changed</strong>. A server on the old table does not fail; it puts the wrong number on the wire for a quarter of the items it knows, and the client shows something else.</p><hr><h3 id="item-tags" tabindex="-1">item_tags <a class="header-anchor" href="#item-tags" aria-label="Permalink to “item_tags”">​</a></h3><blockquote><p><code>const</code> <strong>item_tags</strong>: <code>Readonly</code>&lt;<code>Record</code>&lt;<code>string</code>, readonly <code>string</code>[]&gt;&gt; = <code>item_tags_data</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L109" target="_blank" rel="noreferrer">index.ts:109</a></p><p>Tag name to the items carrying it.</p><p>A recipe may ask for &quot;any plank&quot; rather than name the thirteen, and this is the only place that question has an answer. Typed by the question rather than by the file: a caller asks about a tag name a recipe gave it, which is a string and not one of the 77 keys the JSON happens to hold.</p><hr><h3 id="java-entity-attributes" tabindex="-1">java_entity_attributes <a class="header-anchor" href="#java-entity-attributes" aria-label="Permalink to “java_entity_attributes”">​</a></h3><blockquote><p><code>const</code> <strong>java_entity_attributes</strong>: <code>Record</code>&lt;<code>string</code>, <a href="#javaentityattributes"><code>JavaEntityAttributes</code></a>&gt; = <code>java_entity_attributes_data</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L163" target="_blank" rel="noreferrer">index.ts:163</a></p><p>Every attribute Java Edition&#39;s entity classes declare, by entity type.</p><p>2619 values over 93 types, dumped from the pinned unobfuscated 26.3 server jar by <code>utils/java-dump/run.mjs</code>. Bedrock publishes the same stats as entity components, so this is what a cross-edition check compares those components against; the two editions genuinely differ on some of them, which is a finding rather than a defect.</p><hr><h3 id="java-entity-navigation" tabindex="-1">java_entity_navigation <a class="header-anchor" href="#java-entity-navigation" aria-label="Permalink to “java_entity_navigation”">​</a></h3><blockquote><p><code>const</code> <strong>java_entity_navigation</strong>: <code>Record</code>&lt;<code>string</code>, <a href="#javaentitynavigationentry"><code>JavaEntityNavigationEntry</code></a>&gt; = <code>java_entity_navigation_data</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L180" target="_blank" rel="noreferrer">index.ts:180</a></p><p>The path navigation Java&#39;s mob classes construct, keyed by Java entity identifier.</p><hr><h3 id="jigsaw-structure-data" tabindex="-1">jigsaw_structure_data <a class="header-anchor" href="#jigsaw-structure-data" aria-label="Permalink to “jigsaw_structure_data”">​</a></h3><blockquote><p><code>const</code> <strong>jigsaw_structure_data</strong>: <code>Buffer</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L128" target="_blank" rel="noreferrer">index.ts:128</a></p><p>The jigsaw structure rules, as <code>JigsawStructureDataPacket</code> carries them: one network NBT compound, the payload of the packet a Bedrock Dedicated Server 1.26.51.1 sent. A client at protocol 2193 refuses to join a server that has not sent this before <code>StartGamePacket</code>.</p><hr><h3 id="legacy-item-aliases" tabindex="-1">legacy_item_aliases <a class="header-anchor" href="#legacy-item-aliases" aria-label="Permalink to “legacy_item_aliases”">​</a></h3><blockquote><p><code>const</code> <strong>legacy_item_aliases</strong>: <code>Readonly</code>&lt;<code>Record</code>&lt;<code>string</code>, <code>string</code>&gt;&gt; = <code>legacy_item_aliases_data.simple</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L68" target="_blank" rel="noreferrer">index.ts:68</a></p><p>Legacy Bedrock item identifiers still used by vanilla definitions, mapped to current names.</p><hr><h3 id="legacy-item-aux-aliases" tabindex="-1">legacy_item_aux_aliases <a class="header-anchor" href="#legacy-item-aux-aliases" aria-label="Permalink to “legacy_item_aux_aliases”">​</a></h3><blockquote><p><code>const</code> <strong>legacy_item_aux_aliases</strong>: <code>Readonly</code>&lt;<code>Record</code>&lt;<code>string</code>, <code>Readonly</code>&lt;<code>Record</code>&lt;<code>string</code>, <code>string</code>&gt;&gt;&gt;&gt; = <code>legacy_item_aliases_data.complex</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/93b81b3a502309f2b7c7dcc8481275e22762ddb8/packages/bedrock-data/src/index.ts#L71" target="_blank" rel="noreferrer">index.ts:71</a></p><p>Legacy Bedrock item identifiers whose auxiliary value selects a current item name.</p>`,240)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};